function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 strings.';
  const ok = s => typeof s === 'string' && /^[0-9]+$/.test(s) && !(s.length > 1 && s[0] === '0');
  if (nums.some(s => !ok(s) || s.length > 100)) return 'Each nums[i] is 1 to 100 digits with no leading zero.';
  if (!ok(target) || target.length < 2 || target.length > 100) return 'target is 2 to 100 digits with no leading zero.';
  return null;
}

