function numOfPairs(nums, target) {
  const count = new Map();
  for (const word of nums) {
    count.set(word, (count.get(word) ?? 0) + 1);
  }

  let pairs = 0;
  for (let cut = 1; cut < target.length; cut++) {
    const prefix = target.slice(0, cut);
    const suffix = target.slice(cut);
    const first = count.get(prefix) ?? 0;
    const second = count.get(suffix) ?? 0;
    if (prefix === suffix) {
      pairs += first * (first - 1);
    } else {
      pairs += first * second;
    }
  }
  return pairs;
}

