function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const alphabet = rand() < 0.4 ? '7' : rand() < 0.5 ? '12' : '1203';
  const digit = () => alphabet[int(0, alphabet.length - 1)];
  const lead = () => { let d = digit(); while (d === '0') d = digit(); return d; };
  const word = length => { let s = lead(); while (s.length < length) s += digit(); return s; };
  const target = word(large ? int(60, 100) : int(2, 6));
  const n = large ? 100 : int(2, 8);
  const nums = [];
  while (nums.length < n) {
    const pick = rand();
    const cut = int(1, target.length - 1);
    let piece;
    if (pick < 0.4) piece = target.slice(0, cut);
    else if (pick < 0.8) piece = target.slice(cut);
    else piece = word(int(1, large ? target.length : 4));
    if (piece.length > 1 && piece[0] === '0') continue;
    nums.push(piece);
  }
  return [nums, target];
}
